/* Include and run SAS code from an external file */
%include "1_classify_analysts\0_clean_IBES.sas";
%include "1_classify_analysts\1_merge_ciq_analyst.sas";
%include "1_classify_analysts\2a_var_classification.sas";
%include "1_classify_analysts\2b_var_aggregation.sas";

%let outfile = ea_participation;
data perm.&outfile.; set x12;
run;

proc export data=x12
	outfile= "../data/&outfile..dta"
	dbms=stata
	replace;
run;

/* Perform PCA for the current group */
PROC PRINCOMP DATA=&dataset OUT=prin_out&i OUTSTAT=stats&i;
VAR &group;

DATA &varout.&i;
    SET prin_out&i(KEEP=prin1 permno mostimportantdateutc);
    RENAME prin1 = &varout._&suffix;
RUN;

/* Merge prin_sir back into the main file */
PROC SORT DATA=&varout.&i; BY permno mostimportantdateutc; RUN;

%let outfile = engage_class_2;
data perm.&outfile ; set z1 ;
run;

proc export data = perm.&outfile
	outfile = "../data/engage_class_2.dta"
	dbms = dta replace;
run;
